    static std::array<std::uint8_t, TAG_SIZE> poly1305(const std::array<std::uint8_t, 32> &one_time_key, const std::string &message);

    // AEAD_CHACHA20_POLY1305 (RFC 8439 section 2.8). seal returns ciphertext | tag.
